function deriveThemePaletteFromAccent(hex, light = false) {
	const m = /^#?([0-9a-f]{6})$/i.exec(hex || "");
	const clean = m ? "#" + m[1].toLowerCase() : "#ff7a1a";
	const n = parseInt(clean.slice(1), 16);
	const r = (n >> 16) / 255;
	const g = (n >> 8 & 255) / 255;
	const b = (n & 255) / 255;
	const mx = Math.max(r, g, b);
	const mn = Math.min(r, g, b);
	const d = mx - mn;
	const l = (mx + mn) / 2;
	let h = 0;
	if (d) {
		h = mx === r ? (g - b) / d % 6 : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
		h = Math.round(h * 60);
		if (h < 0) h += 360;
	}
	const sat = d ? Math.round(Math.min(.85, d / (1 - Math.abs(2 * l - 1))) * 100) : 0;
	if (light) return {
		accent: clean,
		pe: clean,
		bg: `hsl(${h} 18% 95%)`,
		chip: `hsla(${h}, 20%, 100%, 0.82)`,
		np: `hsla(${h}, 20%, 98%, 0.94)`,
		sh: `hsla(${h}, 20%, 99%, 0.97)`,
		fg: "#141418",
		mu: "#52545d"
	};
	return {
		accent: clean,
		pe: `hsl(${h} ${Math.max(sat, 30)}% 76%)`,
		bg: `hsl(${h} 34% 6%)`,
		chip: `hsla(${h}, 34%, 13%, 0.74)`,
		np: `hsla(${h}, 30%, 10%, 0.9)`,
		sh: `hsla(${h}, 32%, 11%, 0.95)`,
		fg: "#f1f5f8",
		mu: `hsl(${h} 16% 68%)`
	};
}
