function fontCssFor(font) {
	switch (font) {
		case "medieval": return "'IM Fell English', 'Cinzel', Georgia, serif";
		case "gothic": return "'Cormorant Garamond', 'Cinzel', Georgia, serif";
		case "serif": return "'Cinzel', Georgia, serif";
		case "mono": return "'JetBrains Mono', ui-monospace, monospace";
		case "cinema": return "'Rajdhani', 'Plus Jakarta Sans', system-ui, sans-serif";
		default: return "'Plus Jakarta Sans', system-ui, -apple-system, sans-serif";
	}
}
function toRoman(num) {
	const vals = [
		[100, "C"],
		[90, "XC"],
		[50, "L"],
		[40, "XL"],
		[10, "X"],
		[9, "IX"],
		[5, "V"],
		[4, "IV"],
		[1, "I"]
	];
	let n = Math.max(1, num);
	let out = "";
	for (const [v, sym] of vals) while (n >= v) {
		out += sym;
		n -= v;
	}
	return out;
}
